_vioc_upg = [CTI_UPGRADE_BARRACKS, CTI_UPGRADE_LIGHT, CTI_UPGRADE_HEAVY, CTI_UPGRADE_AIR, -1, -1, CTI_UPGRADE_NAVAL];

_c = []; //--- Classname
_p = []; //--- Picture ('' = auto)
_n = []; //--- Name ('' = auto; ["formato %1"] = nombre del juego con agregado)
_o = []; //--- Price
_t = []; //--- Build time
_u = []; //--- Upgrade level needed
_f = []; //--- Built from Factory
_s = []; //--- Script
_d = []; //--- Extra Distance (From Factory)

//--- [clase, fabrica, nivel, precio base, armado, multiplicador, nombre, script, distancia, apoyo de EE.UU.]
