{
	_x params ["_cls", "_fac", "_lvl", "_base", "_arm", "_mult", "_name", "_scr", "_dist", "_isUS"];
	if ((!_isUS || {_vioc_us}) && {(_vioc_caps select _fac) >= _lvl} && {isClass (configFile >> "CfgVehicles" >> _cls)}) then {
		_c pushBack _cls;
		_p pushBack "";
		_n pushBack (if (_isUS && {_name isEqualTo ""}) then {_vioc_usn} else {_name});
		_o pushBack ([_base, _lvl, _arm, _mult] call CTI_CO_FNC_GetCalculatedUnitsPrize);
		_t pushBack ([_fac, _lvl] call CTI_CO_FNC_GetCalculatedBuildtime);
		_u pushBack _lvl;
		_f pushBack _fac;
		_s pushBack _scr;
		_d pushBack _dist;
		private _vioc_ui = _vioc_upg select _fac;
		if (_vioc_ui >= 0 && {_lvl > (_upgrade_levels select _vioc_ui)}) then {_upgrade_levels set [_vioc_ui, _lvl]};
	};
} forEach _vioc_rows;

//--- Camion de salvamento (solo la nacion principal del bando, como las demas)
_vioc_main = missionNamespace getVariable [format ["CTI_%1_MAINNATIONS", _side], []];
if ((count _vioc_main == 0 || {(_vioc_main select 0) isEqualTo CTI_COL_ID}) && {CTI_ADDON_CHARLIECO < 1}) then {
	_vioc_salv = (["vurtual_m923", "B_COArmy_M1084_Camion_Tranporte_M2_WDL_01", "rhsusf_M1084A1P2_WD_fmtv_usarmy"] select {isClass (configFile >> "CfgVehicles" >> _x)}) param [0, ""];
	if (_vioc_salv != "") then {
		{
			_c pushBack (_x select 0);
			_p pushBack "";
			_n pushBack "Salvager Truck";
			_o pushBack CTI_VEHICLES_SALVAGER_PRICE;
			_t pushBack ([CTI_FACTORY_REPAIR, 0] call CTI_CO_FNC_GetCalculatedBuildtime);
			_u pushBack 0;
			_f pushBack CTI_FACTORY_REPAIR;
			_s pushBack [_vioc_salv, _x select 1];
			_d pushBack 10;
		} forEach [[format ["CTI_Salvager_%1", _faction], "salvager"], [format ["CTI_Salvager_Independent_%1", _faction], "salvager-independent"]];
	};
};

if (CTI_Log_Level >= CTI_Log_Information) then {["INFORMATION", "FILE: Common\Config\Units\units_COL_RHS.sqf", format ["VIOC nation_col: %1 unidades de Colombia para %2 (apoyo de EE.UU.: %3)", count _c, _side, _vioc_us]] call CTI_CO_FNC_Log};

[_side, _faction, _c, _p, _n, _o, _t, _u, _f, _s, _d] call compile preprocessFileLineNumbers "Common\Config\Units\Set_Units.sqf";

/*
