/*
	VIOC_nation_col.sqf - funciones de Colombia que usan otros scripts (Common\Init\Init_Common.sqf lo compila en
	cada maquina, solo si Colombia esta en la partida: CTI_COL_SIDE >= 0).
	VIOC nation_col (agregado por tools/vio_build.py; copia configurada, no es del autor de la mision). Colombia como
	nacion de VIO-BECTI-CW: mod "Colombian Armed Forces RHS" (Workshop 831775240; requiere CBA, RHSUSAF y RHSAFRF).
	Bando: parametro de lobby CTI_COL_SIDE (-1 no, 0 Oeste, 1 Este). Lo que el mod no tiene (carros, orugas modernos,
	artilleria autopropulsada, HIMARS, AH-64, A-10, CH-47, Javelin, Stinger) son clases de RHS de EE. UU. marcadas
	"(apoyo EE.UU.)" que se compran DESDE EL NIVEL MEDIO de cada fabrica (cuartel 1 de 0-2, solo 4 especialistas;
	ligera, pesada y aerea 2 de 0-5; tienda 2 de 0-3), si VIOC_COL_US_SUPPORT = 1 y EE. UU. no esta en el mismo bando
	(si lo esta, las trae su propia nacion). Toda clase se comprueba con isClass: lo que falta se salta.
	- VIOC_COL_fnc_soDress [unidad, estilo, paquete]: ropa y armas de las operaciones especiales colombianas del parche
	  ai_specops (Lanceros, FUDRA, AFEUR, Comandos Jungla de la Policia, Buzos Tacticos, Paracaidistas). La llama
	  VIOC_fnc_soGear (gancho de nation_col) antes del supresor y las gafas nocturnas del paquete. Cada cambio es
	  transaccional: uniforme/chaleco nuevos solo si existen, lo que llevaba la prenda vieja pasa a la nueva (o al
	  chaleco/mochila); el arma principal y la pistola con las funciones de ai_loadouts (VIOC_LO_fnc_swapPrimary /
	  swapHandgun), que dejan todo como estaba si algo no cabe. El jefe del equipo (clase "lead" del paquete) lleva la
	  boina o el casco de su unidad.
	Consola (servidor; LOCAL EXEC en partida alojada): VIOC_COL_STATUS = [CTI_COL_SIDE, soldados vestidos, cambios].
*/
if (!isNil "VIOC_COL_INIT") exitWith {};
VIOC_COL_INIT = true;
VIOC_COL_STATUS = [missionNamespace getVariable ["CTI_COL_SIDE", -1], 0, 0];

//--- estilo -> [uniformes, uniformes del jefe, cabeza, cabeza del jefe, chalecos, gafas, armas principales, pistolas]
VIOC_COL_DRESS = createHashMapFromArray [
	["lanceros", [["bm4jun"], ["survival_uniform_woodland"], ["col_bm4_boonie_mcjj"], ["SP_Beret2_Black"], [], ["COL_Bandanna_Shades_W", "COL_GCombat_W"], ["col_galil_ace", "col_galil_ace23"], []]],
	["fudra", [[], [], ["col_bm4_opscore_cover_MCJ_pelt", "col_bm4_opscore_cover_MCJ"], ["SP_Beret2_Black1"], ["bm4_jun_mbavmc", "bm4_jun_mbavmc_l"], ["COL_GCombat_W"], [], []]],
	["afeur", [["g3_comandoscol2"], ["g3_comandoscol2"], ["col_bm4_opscore_cover_MCJ_pelt_nsw", "col_bm4_opscore_cover_MCJ_pelt_cam"], ["SP_Beret2_Red"], ["bm4_jun_mbavmc"], ["COL_GCombat_W", "tacticool"], ["col_tavor_carbine"], []]],
	["jungla", [["col_bm4_g3_mcj"], ["col_bm4_g3_mcj"], ["COL_BoonieHat_W"], ["COL_Beret_MOE"], ["COL_PlateCarrier3_W"], ["COL_Bandanna_Shades_W"], ["col_galil_ace", "rhs_weap_m4a1_blockII_bk"], ["rhsusf_weap_glock17g4"]]],
	["buzos", [[], [], ["col_bm4_opscore_cover_MCJ_pelt", "col_bm4_opscore_cover_MCJ_pelt_nsw"], ["col_bm4_opscore_cover_MCJ_pelt_nsw"], [], ["G_I_Diving_L"], [], []]],
	["para", [[], [], ["colombia_col_casco_lwh_e"], ["SP_Beret2_Blue"], [], [], [], []]]
];

//--- una clase al azar de la lista que exista en el contenedor dado ("" si ninguna)
VIOC_COL_fnc_pickOk = {
	params ["_list", ["_cont", "CfgWeapons"]];
	private _ok = _list select {isClass (configFile >> _cont >> _x)};
	if (_ok isEqualTo []) exitWith {""};
	selectRandom _ok
};

//--- pone objetos en el primer contenedor donde quepan, en el orden dado ("u" uniforme, "v" chaleco, "b" mochila)
VIOC_COL_fnc_put = {
	params ["_u", "_items", "_order"];
	{
		private _it = _x;
		{
			private _done = call {
				if (_x == "u") exitWith {if (_u canAddItemToUniform _it) then {_u addItemToUniform _it; true} else {false}};
				if (_x == "v") exitWith {if (_u canAddItemToVest _it) then {_u addItemToVest _it; true} else {false}};
				if (_u canAddItemToBackpack _it) then {_u addItemToBackpack _it; true} else {false}
			};
			if (_done) exitWith {};
		} forEach _order;
	} forEach _items;
};

VIOC_COL_fnc_setUniform = {
	params ["_u", "_new"];
	private _old = uniform _u;
	if (_new == "" || {_new == _old}) exitWith {false};
	private _items = uniformItems _u;
	removeUniform _u;
	_u forceAddUniform _new;
	if (uniform _u == "" && {_old != ""}) then {_u forceAddUniform _old};
	[_u, _items, ["u", "v", "b"]] call VIOC_COL_fnc_put;
	uniform _u == _new
};

VIOC_COL_fnc_setVest = {
	params ["_u", "_new"];
	private _old = vest _u;
	if (_new == "" || {_new == _old}) exitWith {false};
	private _items = vestItems _u;
	removeVest _u;
	_u addVest _new;
	if (vest _u == "" && {_old != ""}) then {_u addVest _old};
	[_u, _items, ["v", "u", "b"]] call VIOC_COL_fnc_put;
	vest _u == _new
};

VIOC_COL_fnc_soDress = {
	params [["_u", objNull, [objNull]], ["_style", "", [""]], ["_pkg", createHashMap]];
	if (isNull _u || {!alive _u}) exitWith {false};
	private _d = VIOC_COL_DRESS getOrDefault [_style, []];
	if (count _d < 8) exitWith {false};
	_d params ["_uni", "_uniL", "_head", "_headL", "_vests", "_gogs", "_prim", "_hand"];
	private _lead = (toLower typeOf _u) in ((_pkg getOrDefault ["vlead", []]) apply {toLower _x});
	private _n = 0;
	//--- 1) uniforme
	private _nu = [[_uni, _uniL] select (_lead && {count _uniL > 0})] call VIOC_COL_fnc_pickOk;
	if (_nu != "" && {[_u, _nu] call VIOC_COL_fnc_setUniform}) then {_n = _n + 1};
	//--- 2) chaleco
	private _nv = [_vests] call VIOC_COL_fnc_pickOk;
	if (_nv != "" && {[_u, _nv] call VIOC_COL_fnc_setVest}) then {_n = _n + 1};
	//--- 3) casco, gorra o boina (el jefe, la de su unidad)
	private _nh = [[_head, _headL] select (_lead && {count _headL > 0})] call VIOC_COL_fnc_pickOk;
	if (_nh != "" && {_nh != headgear _u}) then {
		private _oh = headgear _u;
		removeHeadgear _u;
		_u addHeadgear _nh;
		if (headgear _u == "" && {_oh != ""}) then {_u addHeadgear _oh} else {_n = _n + 1};
	};
	//--- 4) gafas o panoleta (60 %)
	private _ng = [_gogs, "CfgGlasses"] call VIOC_COL_fnc_pickOk;
	if (_ng != "" && {random 1 < 0.6}) then {
		removeGoggles _u;
		_u addGoggles _ng;
		if (goggles _u == _ng) then {_n = _n + 1};
	};
	//--- 5) arma principal y pistola de la unidad (funciones transaccionales de ai_loadouts, si estan)
	private _nw = [_prim] call VIOC_COL_fnc_pickOk;
	if (_nw != "" && {_nw != primaryWeapon _u} && {primaryWeapon _u != ""} && {!isNil "VIOC_LO_fnc_swapPrimary"}) then {
		if ([_u, _nw, "rifle", "COL"] call VIOC_LO_fnc_swapPrimary) then {_n = _n + 1};
	};
	private _np = [_hand] call VIOC_COL_fnc_pickOk;
	if (_np != "" && {_np != handgunWeapon _u} && {handgunWeapon _u != ""} && {!isNil "VIOC_LO_fnc_swapHandgun"}) then {
		if ([_u, _np] call VIOC_LO_fnc_swapHandgun) then {_n = _n + 1};
	};
	VIOC_COL_STATUS set [1, (VIOC_COL_STATUS select 1) + 1];
	VIOC_COL_STATUS set [2, (VIOC_COL_STATUS select 2) + _n];
	true
};

